use std::env;
use std::io::{self, Write};

mod inflection;

fn main() -> io::Result<()> {
    inflection::Inflector::initialize();

    let args: Vec<String> = env::args().collect();
    let mut results = Vec::new();

    for i in 1..args.len().min(6) {
        let word = &args[i];

        results.push(inflection::Inflector::pluralize(word));
        results.push(inflection::Inflector::camelize(word));
        if i % 2 == 0 {
            results.push(inflection::Inflector::underscore(word));
        }
    }

    let stdout = io::stdout();
    let mut out = stdout.lock();

    for result in &results {
        write_line(&mut out, result)?;
    }

    if args.len() > 1 {
        write_number(&mut out, inflection::Inflector::isPlural(&args[1]))?;
        write_number(&mut out, inflection::Inflector::isSingular(&args[1]))?;
        let value = inflection::Inflector::demodulize(&format!("Module::{}", args[1]));
        write_line(&mut out, &value)?;
    }

    Ok(())
}

fn write_line(out: &mut impl Write, value: &str) -> io::Result<()> {
    writeln!(out, "{value}")?;
    out.flush()
}

fn write_number(out: &mut impl Write, value: bool) -> io::Result<()> {
    writeln!(out, "{}", if value { 1 } else { 0 })?;
    out.flush()
}

