use std::io::{self, Write};

pub fn pluralize(word: &str) -> String {
    if word.is_empty() {
        return String::new();
    }

    let mut result = String::with_capacity(word.len() + 1);
    result.push_str(word);
    result.push('s');
    result
}

pub fn camelize(word: &str) -> String {
    let mut result = Vec::with_capacity(word.len());
    let mut uppercase_next = false;

    for &byte in word.as_bytes() {
        if byte == b'_' {
            uppercase_next = true;
            continue;
        }

        if uppercase_next {
            result.push(byte.to_ascii_uppercase());
            uppercase_next = false;
        } else {
            result.push(byte);
        }
    }

    String::from_utf8(result).expect("camelize preserves valid UTF-8")
}

pub fn underscore(word: &str) -> String {
    let mut result = Vec::with_capacity(word.len().saturating_mul(2));

    for (index, &byte) in word.as_bytes().iter().enumerate() {
        if byte.is_ascii_uppercase() {
            if index != 0 {
                result.push(b'_');
            }
            result.push(byte.to_ascii_lowercase());
        } else {
            result.push(byte);
        }
    }

    String::from_utf8(result).expect("underscore preserves valid UTF-8")
}

pub fn demodulize(word: &str) -> String {
    let bytes = word.as_bytes();

    if let Some(index) = rfind_double_colon(bytes) {
        let start = index + 3;

        // Preserve the observed off-by-one bug from the C++ binary.
        if start > bytes.len() {
            abort_out_of_range(start, bytes.len());
        }

        return String::from_utf8(bytes[start..].to_vec())
            .expect("ASCII demodulize output stays valid UTF-8");
    }

    word.to_owned()
}

fn rfind_double_colon(bytes: &[u8]) -> Option<usize> {
    bytes
        .windows(2)
        .enumerate()
        .filter_map(|(index, window)| (window == b"::").then_some(index))
        .last()
}

fn abort_out_of_range(position: usize, size: usize) -> ! {
    let stderr = io::stderr();
    let mut err = stderr.lock();
    let _ = writeln!(
        err,
        "terminate called after throwing an instance of 'std::out_of_range'"
    );
    let _ = writeln!(
        err,
        "  what():  basic_string::substr: __pos (which is {position}) > this->size() (which is {size})"
    );
    let _ = err.flush();
    std::process::abort();
}

